function pyBox(x,y,w,h,col,r=0){noStroke();fill(col);rect(x,y,w,h,r);}
function pyLine(x,y,a,b,col='#796C69',sw=4){stroke(col);strokeWeight(sw);line(x,y,a,b);noStroke();}
function pyDisc(x,y,d,col){noStroke();fill(col);circle(x,y,d);}
function pyText(s,x,y,size=28,col='#755E56'){noStroke();fill(col);textFont('Noto Serif SC');textStyle(NORMAL);textSize(size);textAlign(CENTER,CENTER);text(s,x,y);}
function pySky(t,warm=true){const c=drawingContext,g=c.createLinearGradient(0,0,0,H);g.addColorStop(0,warm?'#A6C5C8':'#384A64');g.addColorStop(.7,warm?'#F3D8AD':'#B0989A');g.addColorStop(1,warm?'#F8E6C7':'#D7B897');c.fillStyle=g;c.fillRect(0,0,W,H);for(let j=0;j<6;j++){let x=(j*410+t*9)%2450-240;noStroke();fill(warm?'#F8F0DC':'#78849A');ellipse(x,100+j%3*65,260,35);}}
function pyFloor(warm=true){pyBox(0,730,W,350,warm?'#C4A78A':'#8E8380');for(let j=0;j<8;j++)pyLine(0,760+j*45,W,760+j*45,warm?'#D4BCA0':'#A1958A',2);for(let j=0;j<9;j++)pyLine(180+j*230,730,-250+j*320,1080,warm?'#D4BCA0':'#A1958A',2);}
function pyHillBack(t,warm=true){pySky(t,warm);noStroke();fill(warm?'#9EBAA5':'#657B87');beginShape();vertex(0,680);for(let x=0;x<=2000;x+=80)vertex(x,580+Math.sin(x*.002)*80);vertex(W,H);vertex(0,H);endShape(CLOSE);fill(warm?'#B9C5A1':'#8B9C99');beginShape();vertex(0,760);for(let x=0;x<=2000;x+=80)vertex(x,690+Math.sin(x*.003+1)*60);vertex(W,H);vertex(0,H);endShape(CLOSE);}
function pyTree(x,y,t,k=1,flower=false){push();translate(x,y);scale(k);pyLine(0,0,8,-290,'#8F7967',23);pyLine(3,-180,-65,-260,'#8F7967',12);for(let j=0;j<7;j++){let xx=(j%3-1)*65+Math.sin(t*.8+j)*6,yy=-260-Math.floor(j/3)*55;pyDisc(xx,yy,140,flower?['#E9BBAD','#E6B4A8','#EDD0BA'][j%3]:['#A6B79A','#98AC8E','#B6C3A0'][j%3]);}pop();}
function pyBench(x,y){for(let j=0;j<3;j++)pyBox(x,y-80+j*22,260,15,'#A38168',5);pyBox(x-7,y,274,22,'#AB8769',6);pyBox(x+20,y+22,14,80,'#756D68');pyBox(x+230,y+22,14,80,'#756D68');}
function pyBuildings(t,warm=true){for(let j=0;j<8;j++){let x=j*270-70,y=400-j%3*65;pyBox(x,y,220,340,warm?'#B7AF9D':'#657287',5);pyBox(x-8,y-16,236,20,warm?'#A89E8B':'#56667C',4);for(let a=0;a<3;a++)for(let b=0;b<3;b++)pyBox(x+25+a*60,y+36+b*80,30,48,warm?'#E9DDC2':'#DCC09A',3);}}
function pyLamp(x,y,t,warm){pyBox(x-6,y,12,260,'#786E6C');pyLine(x,y,x+45,y-25,'#786E6C',8);pyDisc(x+45,y-30,55,'#E8C191');if(!warm){let c=drawingContext,g=c.createRadialGradient(x+45,y-30,5,x+45,y-30,125);g.addColorStop(0,'#FFE5B17F');g.addColorStop(1,'#FFE5B100');c.fillStyle=g;c.fillRect(x-80,y-155,250,250);}pyDisc(x+45,y-30,29,'#FBE0A8');}
function pyPlant(x,y,t,k=1){push();translate(x,y);scale(k);pyBox(-26,0,52,58,'#B28A73',6);for(let j=0;j<5;j++){let xx=(j-2)*22+Math.sin(t*1.2+j)*8;pyLine(0,5,xx,-75-j%2*22,'#8EAA87',4);noStroke();fill('#A9BC96');ellipse(xx,-75-j%2*22,40,17);}pop();}
function pyLantern(x,y,t,k=1){push();translate(x,y);scale(k);rotate(Math.sin(t*.9+x)*.035);pyLine(0,-140,0,-40,'#9E8871',4);pyBox(-40,-40,80,100,'#C98F75',20);pyBox(-31,-28,62,74,'#E7B68C',16);pyLine(-40,-15,40,-15,'#BE8C70',3);pyLine(-40,35,40,35,'#BE8C70',3);pyLine(0,60,0,90,'#C9A582',3);pop();}
function pyClock(x,y,t){pyDisc(x,y,150,'#BAA080');pyDisc(x,y,130,'#EDE1C4');for(let j=0;j<12;j++){let a=j*TAU/12;pyLine(x+Math.sin(a)*49,y-Math.cos(a)*49,x+Math.sin(a)*57,y-Math.cos(a)*57,'#9C8770',3);}let a=t*.07;pyLine(x,y,x+Math.sin(a)*43,y-Math.cos(a)*43,'#837265',5);pyLine(x,y,x+Math.sin(a*.3)*27,y-Math.cos(a*.3)*27,'#837265',7);pyDisc(x,y,12,'#A88B73');}
function pyEnvironment(t,s,p){let loc=s.location,warm=!['tavern','window','rooftop'].includes(loc);pySky(t,warm);
 if(['river','bridge'].includes(loc)){pyHillBack(t);pyBox(0,675,W,405,'#8DAEAC');for(let j=0;j<35;j++){let x=(j*160+t*30)%2200-100;pyLine(x,705+j%8*45,x+60,705+j%8*45,'#BBD0BD',3);}pyBox(0,650,W,95,'#D2BA98');for(let j=0;j<12;j++)pyBox(j*175,535,15,130,'#B9A48B');pyBox(0,525,W,18,'#D8C5A8');pyBox(0,745,880,335,'#BCA58D');pyTree(150,750,t,.75);pyBench(1180,740);}
 else if(['road','hill'].includes(loc)){pyHillBack(t,loc==='hill');pyFloor();pyTree(150,740,t,1);pyTree(1700,770,t,.8);pyBench(1280,780);if(loc==='hill'){pyDisc(1330,230,125,'#F4D59A');for(let j=0;j<8;j++){let a=j*TAU/8;pyLine(1330+Math.cos(a)*90,230+Math.sin(a)*90,1330+Math.cos(a)*150,230+Math.sin(a)*150,'#EFD2A0',6);}}else{pyLamp(300,430,t,true);pyBox(1280,440,280,145,'#C7B79B',8);pyText('前 方 · 相 聚',1420,510,25);}}
 else if(loc==='garden'){pyBuildings(t);pyFloor();pyTree(220,770,t,1.2,true);pyTree(1600,770,t,1,true);pyBench(1150,790);for(let j=0;j<5;j++)pyPlant(900+j*100,740,t,.8);}
 else if(['tavern','window'].includes(loc)){
  pyBox(100,110,1720,615,'#BC9B80',12);for(let j=0;j<4;j++){let x=170+j*420;pyBox(x,200,320,390,'#826F65',10);pyBox(x+14,215,292,360,'#819A9D',5);pyBox(x+14,420,292,155,'#A8B6A6');pyLine(x+160,215,x+160,575,'#D5BE9E',12);pyLine(x+14,400,x+306,400,'#D5BE9E',10);}pyFloor(false);pyBox(80,100,1760,65,'#927763',8);pyText('相 聚 小 馆',960,134,36,'#F3DFC0');for(let j=0;j<4;j++)pyLantern(320+j*430,225,t,.9);pyPlant(1770,745,t,1.25);pyBox(80,650,420,110,'#997D66',6);for(let j=0;j<7;j++)pyBox(110+j*49,604,28,70,['#B0A385','#C4987C','#93A99A'][j%3],7);
 }
 else if(loc==='rooftop'){pyBuildings(t,false);pyFloor(false);pyBox(0,650,W,100,'#A49A92');for(let j=0;j<13;j++)pyLine(j*165,650,j*165,545,'#C7BAB0',10);pyBox(0,530,W,16,'#D3BFA5');pyDisc(1530,170,88,'#ECD5AB');pyBench(1200,810);}
 else {pyBuildings(t);pyFloor();pyTree(120,770,t,.8);pyTree(1800,770,t,.9);pyBench(1300,790);if(loc==='station'){pyBox(270,210,1380,105,'#B7AB93',10);pyBox(300,315,30,415,'#AA9C86');pyBox(1590,315,30,415,'#AA9C86');pyText('老 街 · 相 会',960,265,40,'#F5E9CF');pyClock(1460,390,t);}else{for(let j=0;j<4;j++)pyLamp(250+j*440,450,t,true);}}
}
function pyActor(t,x,y,u,action='happy',progress=0,seed=0){
 const e=elasticPose(t-seed*.018,PY_AUDIO,seed*.7);let o={...e,t,boilKey:'friend-'+seed,eyes:'normal',mouth:'smile',lookX:Math.sin(t*.6+seed)*.4};
 if(action==='walk')Object.assign(o,{walk:t/BEAT,aL:e.aL*.7,aR:e.aR*.7,view:'q',flip:seed%2===1});
 if(action==='reflect')Object.assign(o,{eyes:progress<.4?'sad':'normal',mouth:progress<.4?'flat':'smile',lookY:.2,aL:e.aL-.45,aR:e.aR-.45});
 if(action==='sing')Object.assign(o,{mouth:Math.floor(t/BEAT)%2?'open':'grin',aL:e.aL+.65,aR:e.aR+.65,lookY:-.2});
 if(action==='reach')Object.assign(o,{aR:e.aR+.7*ease(progress),aL:e.aL-.25,lookX:1,eyes:'wide'});
 if(action==='strong')Object.assign(o,{eyes:'determined',aL:e.aL+.5,aR:e.aR+.5,lookY:-.3});
 if(action==='support')Object.assign(o,{aL:seed%2?e.aL+.6:e.aL-.15,aR:seed%2?e.aR-.15:e.aR+.6,rot:e.rot+(seed%2?-.06:.06),eyes:'happy'});
 if(action==='happy')Object.assign(o,{eyes:'happy',aL:e.aL+.2,aR:e.aR+.2});
 // Extra diagnostics stay outside the rig options.
 delete o.energy;delete o.beatPhase;clawd(x,y,u,o);
}
function pyCup(x,y,t,k=1,fillLevel=.7){push();translate(x,y);scale(k);pyBox(-34,-80,68,80,'#E8D6B3',10);pyBox(-25,-70+(1-fillLevel)*56,50,fillLevel*56,'#C69D65',5);noFill();stroke('#F4E9CF');strokeWeight(5);ellipse(0,-78,64,13);pop();}
